import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String mode = sc.next();
        Payment p = new Payment();
        if (mode.equals("cash")) {
            double amount = sc.nextDouble();
            System.out.printf("Cash: %.2f%n", p.bill(amount));
        } else {
            int points = sc.nextInt();
            System.out.printf("Points: %.2f%n", p.bill(points));
        }
    }
}
class Payment {
    double bill(double amount) {
        return amount;
    }

    double bill(int points) {
        return points * 0.5;
    }
}

import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Song[] playlist = new Song[n];
        for (int i = 0; i < n; i++) {
            String kind = sc.next();
            Song s;
            if (kind.equals("pop")) {
                s = new PopSong();
            } else if (kind.equals("jazz")) {
                s = new JazzSong();
            } else {
                s = new RockSong();
            }
            s.title = sc.next();
            playlist[i] = s;
        }
        for (int i = 0; i < n; i++) {
            playlist[i].play();
        }
    }
}
class Song {
    String title;

    void play() {
        System.out.println("Now playing: " + title);
    }
}

class PopSong extends Song {
    void play() {
        System.out.println("Pop track: " + title);
    }
}

class JazzSong extends Song {
    void play() {
        System.out.println("Jazz track: " + title);
    }
}

class RockSong extends Song {
    void play() {
        System.out.println("Rock track: " + title);
    }
}

